{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "CJB 090, which differs from the query only by a saturated butyl linker instead of the butenyl linker, entered the brain quickly and demonstrated high brain penetration after intravenous administration, providing strong direct analog evidence for meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Biarylamide analogues containing the same 2-(pyridyl)phenyl amide and N-aryl piperazine core traversed the BBB and displayed excellent brain drug levels in mice after oral dosing, supporting the brain-penetrant phenotype of this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NGB 2904, sharing the 2,3-dichlorophenylpiperazine amide scaffold with a saturated butyl linker, entered the brain quickly and demonstrated high brain penetration after intravenous dosing, reinforcing the transferable CNS exposure of the query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A close analogue with the same dichlorophenylpiperazine amide motif showed excellent brain penetrability in mice after both oral and intravenous dosing, with a brain-to-plasma ratio of 6- to 20-fold, directly demonstrating robust CNS access for this structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analogue of CJB090 and other 2,3-dichlorophenylpiperazine amides with direct in vivo evidence of high brain penetration. The strong transferable experimental evidence overrides the moderate physicochemical prior, supporting a pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct CSF or unbound brain concentration measurement is available for the exact query molecule.",
    "The butenyl linker may alter metabolic stability or transporter interactions relative to the saturated butyl analogues.",
    "P-gp efflux liability was not directly measured for the query, though the close analogues still achieved high brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

